import os
import hashlib
import hmac
import uuid
import tempfile
from pathlib import Path
from PIL import Image
from flask import Flask, request, jsonify, session, send_file
from functools import wraps
import sqlite3

app = Flask(__name__)
app.secret_key = os.urandom(32)

UPLOAD_DIR = Path("/var/app/uploads")
PROCESSED_DIR = Path("/var/app/processed")
UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
PROCESSED_DIR.mkdir(parents=True, exist_ok=True)

def get_db():
    conn = sqlite3.connect('/var/app/images.db')
    conn.execute("""CREATE TABLE IF NOT EXISTS images (
        id TEXT PRIMARY KEY,
        owner_id TEXT NOT NULL,
        filename TEXT NOT NULL,
        status TEXT DEFAULT 'pending',
        processed_path TEXT
    )""")
    return conn

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            return jsonify({"error": "unauthorized"}), 401
        return f(*args, **kwargs)
    return decorated

def generate_image_token(image_id, user_id):
    """Generate an HMAC token binding image access to a user."""
    key = app.secret_key
    msg = f"{image_id}:{user_id}".encode()
    return hmac.new(key, msg, hashlib.sha256).hexdigest()

def verify_image_access(image_id, user_id, token):
    """Verify that the token grants access to this image for this user."""
    expected = generate_image_token(image_id, user_id)
    return hmac.compare_digest(token, expected)

class ImageProcessor:
    """Pipeline for processing uploaded images with multiple stages."""

    ALLOWED_FORMATS = {'JPEG', 'PNG', 'WEBP'}
    MAX_DIMENSION = 4096

    def __init__(self, image_id, owner_id):
        self.image_id = image_id
        self.owner_id = owner_id
        self._validated = False

    def validate(self, file_path):
        """Stage 1: Validate image format and dimensions."""
        try:
            with Image.open(file_path) as img:
                if img.format not in self.ALLOWED_FORMATS:
                    raise ValueError(f"Unsupported format: {img.format}")
                if img.width > self.MAX_DIMENSION or img.height > self.MAX_DIMENSION:
                    raise ValueError("Image too large")
                self._validated = True
                return True
        except (IOError, SyntaxError) as e:
            raise ValueError(f"Invalid image: {e}")

    def process(self, file_path, operations):
        """Stage 2: Apply transformations."""
        if not self._validated:
            raise RuntimeError("Must validate before processing")

        with Image.open(file_path) as img:
            for op in operations:
                if op['type'] == 'resize':
                    w = min(op.get('width', img.width), self.MAX_DIMENSION)
                    h = min(op.get('height', img.height), self.MAX_DIMENSION)
                    img = img.resize((w, h), Image.LANCZOS)
                elif op['type'] == 'rotate':
                    angle = op.get('angle', 0) % 360
                    img = img.rotate(angle, expand=True)
                elif op['type'] == 'thumbnail':
                    size = min(op.get('size', 256), 1024)
                    img.thumbnail((size, size), Image.LANCZOS)

            output_path = PROCESSED_DIR / f"{self.image_id}.png"
            img.save(str(output_path), 'PNG')
            return str(output_path)


@app.route('/upload', methods=['POST'])
@require_auth
def upload_image():
    if 'file' not in request.files:
        return jsonify({"error": "no file"}), 400

    file = request.files['file']
    image_id = str(uuid.uuid4())
    user_id = session['user_id']

    upload_path = UPLOAD_DIR / f"{image_id}_{user_id}"
    file.save(str(upload_path))

    db = get_db()
    db.execute("INSERT INTO images (id, owner_id, filename, status) VALUES (?, ?, ?, ?)",
               (image_id, user_id, file.filename, 'uploaded'))
    db.commit()

    token = generate_image_token(image_id, user_id)
    return jsonify({"image_id": image_id, "token": token}), 201


@app.route('/process/<image_id>', methods=['POST'])
@require_auth
def process_image(image_id):
    user_id = session['user_id']
    token = request.headers.get('X-Image-Token', '')

    if not verify_image_access(image_id, user_id, token):
        return jsonify({"error": "access denied"}), 403

    db = get_db()
    row = db.execute("SELECT * FROM images WHERE id = ?", (image_id,)).fetchone()
    if not row:
        return jsonify({"error": "not found"}), 404

    # Retrieve the actual owner from DB for file path construction
    actual_owner = row[1]
    upload_path = UPLOAD_DIR / f"{image_id}_{actual_owner}"

    if not upload_path.exists():
        return jsonify({"error": "file missing"}), 404

    operations = request.get_json(force=True).get('operations', [])

    processor = ImageProcessor(image_id, actual_owner)
    processor.validate(str(upload_path))
    output_path = processor.process(str(upload_path), operations)

    db.execute("UPDATE images SET status = ?, processed_path = ? WHERE id = ?",
               ('processed', output_path, image_id))
    db.commit()

    return jsonify({"status": "processed", "image_id": image_id})


@app.route('/download/<image_id>', methods=['GET'])
@require_auth
def download_image(image_id):
    user_id = session['user_id']
    token = request.args.get('token', '')

    # Verify token grants access
    if not verify_image_access(image_id, user_id, token):
        return jsonify({"error": "access denied"}), 403

    db = get_db()
    row = db.execute("SELECT * FROM images WHERE id = ? AND status = 'processed'",
                     (image_id,)).fetchone()
    if not row:
        return jsonify({"error": "not found"}), 404

    processed_path = row[4]
    if not processed_path or not os.path.exists(processed_path):
        return jsonify({"error": "file not ready"}), 404

    return send_file(processed_path, mimetype='image/png')


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
